/* =========================================================================
   SKELORA INSTITUTE LOGISTICS SIMULATOR — DOCUMENT CONFIGS
   Each key is a document "slug" used in the URL, e.g. workstation.html?doc=bill-of-lading-sea
   To add a new document exercise, add a new entry here — engine.js does not need to change.
   ========================================================================= */

function ciFOB(d){ return (d.lineItems||[]).reduce((s,r)=>s+(parseFloat(r.qty)||0)*(parseFloat(r.rate)||0),0); }
function ciTotal(d){ const fob=ciFOB(d); const fr=parseFloat(d.freight)||0, ins=parseFloat(d.insurance)||0, disc=parseFloat(d.discount)||0; return fob+fr+ins-disc; }
function dline(label,val){ return `<div style="margin-bottom:4px;"><b style="color:var(--text-3);font-weight:600;">${label}:</b> ${val||"—"}</div>`; }

function plSum(rows, key){ return (rows||[]).reduce((s,r)=>s+(parseFloat(r[key])||0),0); }
function plTotalPackages(d){ return plSum(d.packageDetails,"noOfPackages").toFixed(0); }
function plTotalNet(d){ return plSum(d.packageDetails,"netWeight").toFixed(2); }
function plTotalGross(d){ return plSum(d.packageDetails,"grossWeight").toFixed(2); }
function plTotalVolume(d){ return plSum(d.packageDetails,"volume").toFixed(2); }
function plTotalContainerWt(d){ return plSum(d.plContainers,"grossWeightInContainer").toFixed(2); }
function plWeightCheck(d){
  const pkg = plSum(d.packageDetails,"grossWeight");
  const cont = plSum(d.plContainers,"grossWeightInContainer");
  if(pkg===0 || cont===0) return "Enter both tables to compare";
  const diff = Math.abs(pkg-cont);
  return diff < 1 ? "✓ Matches — package and container totals reconcile" : `⚠ Mismatch of ${diff.toFixed(2)} kg — recheck your entries`;
}

function sbTotalFOB(d){ return plSum(d.sbItems,"fobValueINR").toFixed(2); }
function sbTotalDrawback(d){ return (d.sbItems||[]).reduce((s,r)=>s+(parseFloat(r.fobValueINR)||0)*(parseFloat(r.drawbackRate)||0)/100,0).toFixed(2); }

function boeCifFC(d){ return (parseFloat(d.invoiceValueFOB)||0)+(parseFloat(d.freight)||0)+(parseFloat(d.insurance)||0); }
function boeCifINR(d){ return boeCifFC(d)*(parseFloat(d.exchangeRateCustoms)||0); }
function boeItemBCD(row){ return (parseFloat(row.assessableValue)||0)*(parseFloat(row.bcdRate)||0)/100; }
function boeItemIGST(row){ const av=parseFloat(row.assessableValue)||0; const bcd=boeItemBCD(row); const igstRate=parseFloat(row.igstRate)||0; return (av+bcd)*igstRate/100; }
function boeTotalBCD(d){ return (d.boeItems||[]).reduce((s,r)=>s+boeItemBCD(r),0); }
function boeTotalIGST(d){ return (d.boeItems||[]).reduce((s,r)=>s+boeItemIGST(r),0); }
function boeTotalAV(d){ return plSum(d.boeItems,"assessableValue"); }
function boeTotalSWS(d){ return boeTotalBCD(d)*(parseFloat(d.swsRate)||0)/100; }
function boeGrandTotal(d){ return boeTotalBCD(d)+boeTotalIGST(d)+boeTotalSWS(d)+(parseFloat(d.antiDumpingDuty)||0); }

function lcToleranceInfo(d){
  const map = {"No Tolerance":0, "+/- 5%":5, "+/- 10%":10};
  const pct = map[d.toleranceOption] || 0;
  const amt = parseFloat(d.creditAmount)||0;
  return { pct, min:amt*(1-pct/100), max:amt*(1+pct/100) };
}

function awbRowVolWeight(row){ const l=parseFloat(row.length)||0, w=parseFloat(row.width)||0, h=parseFloat(row.height)||0, pcs=parseFloat(row.pieces)||0; return (l*w*h*pcs)/6000; }
function awbRowChargeable(row){ const gross=parseFloat(row.grossWeight)||0; return Math.max(gross, awbRowVolWeight(row)); }
function awbTotalChargeable(d){ return (d.awbPieces||[]).reduce((s,r)=>s+awbRowChargeable(r),0); }
function awbTotalFreight(d){ return awbTotalChargeable(d)*(parseFloat(d.ratePerKg)||0); }
function awbTotalGross(d){ return plSum(d.awbPieces,"grossWeight"); }
function awbTotalPieces(d){ return plSum(d.awbPieces,"pieces"); }

function lrTotalFreight(d){ return (parseFloat(d.basicFreight)||0)+(parseFloat(d.loadingCharges)||0)+(parseFloat(d.unloadingCharges)||0)+(parseFloat(d.detentionCharges)||0); }
function lrTotalPackages(d){ return plSum(d.lrGoods,"packages"); }
function lrTotalWeight(d){ return plSum(d.lrGoods,"actualWeight"); }

function grnVarianceQty(row){ return (parseFloat(row.receivedQty)||0)-(parseFloat(row.orderedQty)||0); }
function grnLineValue(row){ return (parseFloat(row.receivedQty)||0)*(parseFloat(row.unitPrice)||0); }
function grnTotalOrderedValue(d){ return (d.grnItems||[]).reduce((s,r)=>s+(parseFloat(r.orderedQty)||0)*(parseFloat(r.unitPrice)||0),0); }
function grnTotalReceivedValue(d){ return (d.grnItems||[]).reduce((s,r)=>s+grnLineValue(r),0); }
function grnVarianceValue(d){ return grnTotalReceivedValue(d)-grnTotalOrderedValue(d); }

function insSumInsured(d){ const iv=parseFloat(d.invoiceValueCIF)||0; const pct=parseFloat(d.insurancePercent)||110; return iv*pct/100; }

/* Bill of Exchange helpers (prefixed "bex" — "boe" is already used for Bill of Entry above) */
function bexNumToWords(num){
  const ones=['','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'];
  const tens=['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];
  function chunk(n){
    let s='';
    if(n>=100){ s+=ones[Math.floor(n/100)]+' Hundred '; n%=100; }
    if(n>=20){ s+=tens[Math.floor(n/10)]+' '; n%=10; }
    if(n>0) s+=ones[n]+' ';
    return s.trim();
  }
  let n = Math.floor(num);
  if(n===0) return 'Zero';
  const scales=['','Thousand','Million','Billion'];
  let scaleIdx=0, words=[];
  while(n>0){
    const rem = n%1000;
    if(rem>0) words.unshift(chunk(rem)+(scales[scaleIdx]?' '+scales[scaleIdx]:''));
    n = Math.floor(n/1000);
    scaleIdx++;
  }
  return words.join(' ').trim();
}
function bexAmountWords(d){
  const amt = parseFloat(d.amount)||0;
  const cur = d.currency||'USD';
  const intPart = Math.floor(amt);
  const dec = Math.round((amt-intPart)*100);
  let words = bexNumToWords(intPart)+' '+cur;
  if(dec>0) words += ' and '+dec+'/100';
  return words+' Only';
}
function bexDueDate(d){
  if(!d.billDate) return "—";
  const base = new Date(d.billDate);
  if(isNaN(base.getTime())) return "—";
  if(d.tenor==="At Sight") return `${d.billDate} (payable at sight, on presentation)`;
  let days = 0;
  if(d.tenor==="30 Days after Sight") days=30;
  else if(d.tenor==="60 Days after Sight") days=60;
  else if(d.tenor==="90 Days after Sight") days=90;
  else if(d.tenor==="Other") days=parseInt(d.tenorOtherDays)||0;
  const due = new Date(base.getTime()+days*86400000);
  return due.toISOString().slice(0,10);
}
function bexOverallStatus(d){
  if(d.closeTransaction) return {label:"Closed & Archived", cls:"closed"};
  if(d.settlementOutcome==="Dishonoured — Payment Refused"){
    if(d.protestPrepared || d.legalClaim) return {label:"Dishonoured — Under Protest", cls:"dishonoured"};
    return {label:"Dishonoured — Unpaid", cls:"dishonoured"};
  }
  if(d.paymentReceived) return {label:"Paid & Settled", cls:"paid"};
  if(d.presentedForPayment) return {label:"Presented for Payment", cls:"in-progress"};
  if(d.isEndorsed==="Yes — Endorsed to New Holder" || d.newHolderReceiptConfirmed) return {label:"Endorsed / In Negotiation", cls:"in-progress"};
  if(d.acceptanceStatus==="Accepted" || d.acceptanceStatus==="Accepted Under Reserve") return {label:"Accepted by Drawee", cls:"accepted"};
  if(d.acceptanceStatus==="Refused to Accept") return {label:"Acceptance Refused", cls:"dishonoured"};
  return {label:"Drawn — Pending Acceptance", cls:"pending"};
}

/* Delivery Order helpers */
function doTotalCharges(d){ return (parseFloat(d.portCharges)||0)+(parseFloat(d.thcCharges)||0)+(parseFloat(d.otherCharges)||0); }

/* Delivery Order v2 helpers (full request-to-closure lifecycle) */
function doChargesTotal(d){
  return (d.charges||[]).reduce((s,r)=> s + (parseFloat(r.amount)||0) + (parseFloat(r.tax)||0) - (parseFloat(r.discount)||0), 0);
}
function doNumberGen(d){
  if(!d.requestNumber) return "Not yet generated — enter a Request Number and Issue Date above to generate.";
  const seq = String((d.requestNumber||"").replace(/\D/g,"").slice(-6) || "000001").padStart(6,"0");
  const year = d.issueDate ? new Date(d.issueDate).getFullYear() : new Date().getFullYear();
  return `DO/${year}/${seq}`;
}
function doPhaseStatus(d){
  return [
    {label:"1. Request", done: !!(d.requestNumber && d.duplicateCheck && d.initialVerification)},
    {label:"2. Doc Verification", done: !!(d.verifiedByName && d.approvalDate)},
    {label:"3. Payment & Charges", done: !!d.paymentConfirmed},
    {label:"4. DO Issuance", done: !!(d.consigneeConfirmed && d.cargoDetailsConfirmed && d.digitalSignatureName)},
    {label:"5. Release Authorization", done: !!(d.releaseConfirmedBy && d.gateReleaseAuthorized)},
    {label:"6. Warehouse Delivery", done: !!(d.loadingCompleted && d.dispatchReady)},
    {label:"7. Exit & Handover", done: !!(d.cargoHandedOver && d.receiverSignatureName)},
    {label:"8. Closure & Archiving", done: !!(d.caseClosureDate && d.finalApprovedBy)}
  ];
}
function doOverallStatus(d){
  const phases = doPhaseStatus(d);
  const doneCount = phases.filter(p=>p.done).length;
  if(doneCount===8) return {label:"Case Closed — All 8 Phases Complete", cls:"closed"};
  if(doneCount===0) return {label:"Request Initiated — Awaiting Processing", cls:"pending"};
  return {label:`In Progress — ${doneCount} of 8 Phases Complete`, cls:"in-progress"};
}

/* Bank Guarantee helpers */
function bgClaimExpiry(d){
  if(!d.expiryDate) return "—";
  const base = new Date(d.expiryDate);
  if(isNaN(base.getTime())) return "—";
  const days = parseInt(d.claimPeriodDays)||0;
  const claimEnd = new Date(base.getTime()+days*86400000);
  return claimEnd.toISOString().slice(0,10);
}
function bgIsExpired(d){
  if(!d.expiryDate) return false;
  const claimEnd = new Date(bgClaimExpiry(d));
  if(isNaN(claimEnd.getTime())) return false;
  return claimEnd.getTime() < Date.now();
}

/* Warehouse Receipt helpers (full 6-phase lifecycle: booking through withdrawal & closure) */
function whInquiryIdGen(d){
  if(!d.customerName || !d.requestDate) return "—";
  const seq = String((d.customerName||"").length*7 + (new Date(d.requestDate).getDate()||1)).padStart(4,"0");
  return `INQ-${seq}`;
}
function whBookingNoGen(d){
  if(!d.customerName || !d.requestDate) return "Not yet generated — enter Customer Name and Request Date to generate.";
  const seq = String((d.customerName||"").replace(/[^0-9]/g,"").slice(-6) || String((d.customerName||"").length*13)).padStart(6,"0");
  const year = new Date(d.requestDate).getFullYear() || new Date().getFullYear();
  return `WHB/${year}/${seq}`;
}
function whGrnNoGen(d){
  if(!d.vehicleRegistrationNumber || !d.arrivalDate) return "Not yet generated — enter Vehicle Registration No. and Arrival Date to generate.";
  const seq = String((d.vehicleRegistrationNumber||"").replace(/[^0-9]/g,"").slice(-6) || String((d.vehicleRegistrationNumber||"").length*17)).padStart(6,"0");
  const year = new Date(d.arrivalDate).getFullYear() || new Date().getFullYear();
  return `GRN/${year}/${seq}`;
}
function whGatePassNoGen(d){
  if(!d.vehicleRegistrationNumber || !d.arrivalDate) return "Not yet generated.";
  const seq = String((d.vehicleRegistrationNumber||"").replace(/[^0-9]/g,"").slice(-4) || "0001").padStart(4,"0");
  return `GP-${seq}`;
}
function whInspectionOrderIdGen(d){
  if(!d.arrivalDate) return "Not yet generated.";
  const seq = String((d.grnNumberRef||d.vehicleRegistrationNumber||"").length*19 || 1).padStart(4,"0");
  return `QIO-${seq}`;
}
function whInventoryIdGen(d){
  if(!d.hsCode) return "Not yet generated — enter HS Code to generate.";
  return `INV-${(d.hsCode||"").slice(0,6)}-${String((d.skuCount||"1")).padStart(4,"0")}`;
}
function whCustomerMasterIdGen(d){
  if(!d.companyLegalName) return "Not yet generated — enter Company Legal Name to generate.";
  const seq = String((d.companyLegalName||"").length*11).padStart(5,"0");
  return `CUST-${seq}`;
}
function whrNumberGen(d){
  if(!d.customerName || !d.whrDate) return "Not yet generated — enter Customer Name and WHR Date to generate.";
  const seq = String((d.customerName||"").replace(/[^0-9]/g,"").slice(-6) || String((d.customerName||"").length*23)).padStart(6,"0");
  const year = new Date(d.whrDate).getFullYear() || new Date().getFullYear();
  return `WHR/${year}/${seq}`;
}
function whDaysInStorage(d){
  if(!d.arrivalDate) return 0;
  const base = new Date(d.arrivalDate);
  if(isNaN(base.getTime())) return 0;
  return Math.max(0, Math.floor((Date.now()-base.getTime())/86400000));
}
function whTotalStorageCharges(d){
  const days = whDaysInStorage(d);
  const rate = parseFloat(d.finalStorageCharges)||0;
  return days*rate + (parseFloat(d.finalHandlingCharges)||0) + (parseFloat(d.finalInsuranceCharges)||0) + (parseFloat(d.finalTaxesGst)||0);
}
function whOverallStatus(d){
  if(d.whrStatusFinal==="Closed — Fully Withdrawn") return {label:"Closed — Fully Withdrawn", cls:"closed"};
  if(d.withdrawalRequestReceived && !d.whrStatusFinal) return {label:"Withdrawal In Progress", cls:"in-progress"};
  if(d.whrStatusFinal==="Partially Withdrawn — Balance Receipt Issued") return {label:"Partially Withdrawn — Balance Receipt Issued", cls:"in-progress"};
  if(d.acceptanceDecision==="Rejected") return {label:"Rejected at Quality Inspection", cls:"rejected"};
  if(d.acceptanceDecision==="Quarantine Required") return {label:"Quarantined", cls:"quarantine"};
  if(d.goodsStatusAfterReceiving==="On Hold — Exception") return {label:"On Hold — Exception at Receiving", cls:"rejected"};
  if(d.inventoryStatusFinal==="Stored — Available for Inventory Management") return {label:"Active — Goods in Storage", cls:"active"};
  if(d.bookingPhaseClosed) return {label:"Booked — Awaiting Arrival", cls:"pending"};
  return {label:"Inquiry Stage", cls:"pending"};
}
function whPhaseStatus(d){
  return [
    {n:1, label:"Booking & Registration", done: !!d.bookingPhaseClosed},
    {n:2, label:"Customer Verification", done: !!d.customerApprovedForOperations},
    {n:3, label:"Receiving Operations", done: !!(d.allInspectionsComplete && d.allCountsVerified && d.allDocumentsMatched)},
    {n:4, label:"Quality Inspection", done: d.acceptanceDecision==="Accepted" || d.acceptanceDecision==="Accepted with Remarks"},
    {n:5, label:"Put-Away & WHR Issued", done: !!(d.whrDate && d.recordsArchived)},
    {n:6, label:"Storage / Withdrawal", done: !d.withdrawalRequestReceived || d.whrStatusFinal==="Closed — Fully Withdrawn" || d.whrStatusFinal==="Partially Withdrawn — Balance Receipt Issued"}
  ];
}

/* Proforma Invoice helpers (strict — line discounts, charges stack, amount-in-words, linking) */
function piLineRowTotal(row){
  const qty = parseFloat(row.qty)||0, price = parseFloat(row.unitPrice)||0, disc = parseFloat(row.discount)||0;
  return Math.max(0, qty*price - disc);
}
function piSubtotal(d){ return (d.piLineItems||[]).reduce((s,r)=>s+piLineRowTotal(r),0); }
function piGrandTotal(d){
  const sub = piSubtotal(d);
  const charges = (parseFloat(d.freightCharges)||0)+(parseFloat(d.insuranceCharges)||0)+(parseFloat(d.packingCharges)||0)+(parseFloat(d.documentationCharges)||0)+(parseFloat(d.otherCharges)||0)+(parseFloat(d.taxAmount)||0);
  const discount = parseFloat(d.discountAmount)||0;
  return Math.max(0, sub + charges - discount);
}
function piValidUntil(d){
  if(!d.issueDate) return "—";
  const base = new Date(d.issueDate);
  if(isNaN(base.getTime())) return "—";
  const days = parseInt(d.validityPeriod)||30;
  const until = new Date(base.getTime()+days*86400000);
  return until.toISOString().slice(0,10);
}
function piIsExpired(d){
  const until = new Date(piValidUntil(d));
  if(isNaN(until.getTime())) return false;
  return until.getTime() < Date.now();
}
function piBalancePaymentAmount(d){
  const adv = parseFloat(d.advancePaymentPercent)||0;
  return piGrandTotal(d)*(100-adv)/100;
}
function piNumberToWords(num){
  num = Math.round((parseFloat(num)||0)*100)/100;
  const ones=["","One","Two","Three","Four","Five","Six","Seven","Eight","Nine","Ten","Eleven","Twelve","Thirteen","Fourteen","Fifteen","Sixteen","Seventeen","Eighteen","Nineteen"];
  const tens=["","","Twenty","Thirty","Forty","Fifty","Sixty","Seventy","Eighty","Ninety"];
  function chunk(n){
    let s="";
    if(n>=100){ s+=ones[Math.floor(n/100)]+" Hundred "; n%=100; }
    if(n>=20){ s+=tens[Math.floor(n/10)]+" "; n%=10; }
    if(n>0){ s+=ones[n]+" "; }
    return s;
  }
  let intPart = Math.floor(num);
  const decPart = Math.round((num-intPart)*100);
  if(intPart===0 && decPart===0) return "Zero";
  let words="";
  const crore=Math.floor(intPart/10000000); intPart%=10000000;
  const lakh=Math.floor(intPart/100000); intPart%=100000;
  const thousand=Math.floor(intPart/1000); intPart%=1000;
  const rest=intPart;
  if(crore) words+=chunk(crore)+"Crore ";
  if(lakh) words+=chunk(lakh)+"Lakh ";
  if(thousand) words+=chunk(thousand)+"Thousand ";
  if(rest) words+=chunk(rest);
  words=words.trim();
  if(!words) words="Zero";
  if(decPart>0) words+=` and ${decPart}/100`;
  return words;
}
function piAmountInWordsDisplay(d){
  return `${d.currency||"USD"} ${piNumberToWords(piGrandTotal(d))} Only`;
}

/* ---- Helper functions ported from v2 for the newly added documents (GST e-Invoice, LUT, SOFTEX, ISF, EGM, Transshipment Permit, Marine Insurance Policy, CSR) ---- */
function lutArnGen(d){
  if(!d.gstinLUT || !d.lutDate) return "Not yet generated — enter GSTIN and LUT Date above to generate.";
  const stateCode = String(d.gstinLUT).slice(0,2).replace(/\D/g,"") || "27";
  const seq = String((d.gstinLUT||"").replace(/\D/g,"").slice(-6) || "000001").padStart(6,"0");
  const yy = d.lutDate ? String(new Date(d.lutDate).getFullYear()).slice(-2) : String(new Date().getFullYear()).slice(-2);
  return `AD${stateCode}${yy}${seq}${String(seq.length).padStart(2,"0")}`;
}
function einvIrnGen(d){
  if(!d.supplierGSTINEINV || !d.documentNumberEINV || !d.documentDateEINV) return "Not yet generated — enter Supplier GSTIN, Document Number and Document Date to generate.";
  const seed = `${d.supplierGSTINEINV}|${d.documentNumberEINV}|${new Date(d.documentDateEINV).getFullYear()}`;
  let hash = 0;
  for(let i=0;i<seed.length;i++){ hash = (hash*31 + seed.charCodeAt(i)) >>> 0; }
  let hex = hash.toString(16);
  while(hex.length<64){ hash = (hash*31 + 7) >>> 0; hex += hash.toString(16); }
  return hex.slice(0,64);
}
function einvAckNoGen(d){
  if(!d.documentNumberEINV || !d.documentDateEINV) return "Not yet generated — enter Document Number and Document Date to generate.";
  const seq = String((d.documentNumberEINV||"").replace(/\D/g,"").slice(-10) || "0000000001").padStart(10,"0");
  const yy = String(new Date(d.documentDateEINV).getFullYear()).slice(-2) || "26";
  return `11${yy}${seq}`;
}
function softexRealizationDeadline(d){
  if(!d.invoiceDateSoftex) return "Enter Invoice Date above to calculate.";
  const inv = new Date(d.invoiceDateSoftex);
  if(isNaN(inv.getTime())) return "Invalid date.";
  const deadline = new Date(inv.getTime() + 270*24*60*60*1000);
  return `${deadline.toISOString().slice(0,10)} (270 days from invoice date, per FEMA realization norms)`;
}
function softexUinGen(d){
  if(!d.softexNumber || !d.certificationDateSoftex) return "Not yet generated — enter SOFTEX Number and Certification Date to generate.";
  const seq = String((d.softexNumber||"").replace(/\D/g,"").slice(-6) || "000001").padStart(6,"0");
  const year = new Date(d.certificationDateSoftex).getFullYear() || new Date().getFullYear();
  return `STPI/${year}/${seq}`;
}
function egmClosureCheck(d){
  if(!d.egmNumber || !d.departureDateEGM) return "Not yet closed — enter EGM Number and Departure Date to check closure eligibility.";
  if(d.shortShipmentDeclarationEGM) return "Pending — short-shipment/re-landed goods declared, requires Customs reconciliation before closure.";
  return "Eligible for EGM Closure — all Shipping Bills listed can proceed to duty drawback / GST refund claims.";
}
function isfComplianceCheck(d){
  if(!d.cargoLadenDateISF || !d.filingSubmittedDateISF) return "Enter Filing Submitted Date and Cargo Laden Date above to check compliance.";
  const filed = new Date(d.filingSubmittedDateISF), laden = new Date(d.cargoLadenDateISF);
  if(isNaN(filed.getTime())||isNaN(laden.getTime())) return "Invalid dates.";
  const hoursBefore = (laden - filed) / (1000*60*60);
  if(hoursBefore >= 24) return `Compliant — filed ${hoursBefore.toFixed(0)} hours before lading (24-hour minimum met).`;
  return `NON-COMPLIANT — filed only ${Math.max(hoursBefore,0).toFixed(0)} hours before lading. Minimum 24 hours required; liquidated damages up to $5,000 may apply.`;
}
function tpPermitNoGen(d){
  if(!d.igmNumberTP || !d.certificationDateTP) return "Not yet generated — enter IGM Number and Certification Date to generate.";
  const seq = String((d.igmNumberTP||"").replace(/\D/g,"").slice(-6) || "000001").padStart(6,"0");
  const year = new Date(d.certificationDateTP).getFullYear() || new Date().getFullYear();
  return `TP/${year}/${seq}`;
}
function mipPremiumCalc(d){
  const sum = parseFloat(d.sumInsuredMIP)||0;
  const rate = parseFloat(d.premiumRateMIP)||0;
  if(!sum || !rate) return "Enter Sum Insured and Premium Rate above to calculate.";
  return `${d.currencyMIP||""} ${(sum*rate/100).toFixed(2)}`;
}
function csrLossCalc(d){
  const sound = parseFloat(d.soundValueCSR)||0;
  const damaged = parseFloat(d.damagedValueCSR)||0;
  if(!d.soundValueCSR || !d.damagedValueCSR) return "Enter Sound Value and Damaged Value above to calculate.";
  const loss = Math.max(sound-damaged,0);
  const pct = sound>0 ? (loss/sound*100).toFixed(1) : "0.0";
  return `${d.currencyCSR||""} ${loss.toFixed(2)} (${pct}% depreciation)`;
}

const PI_LINKED_DOCS = ["Commercial Invoice","Shipping Bill","Bill of Lading","Packing List","Certificate of Origin","Insurance Certificate","Inspection Certificate","Fumigation Certificate","Export Declaration","Letter of Credit","Delivery Order","Customs Declaration"];
const PI_LINK_FIELDS = ["confirmedLinkCommercialInvoice","confirmedLinkShippingBill","confirmedLinkBillOfLading","confirmedLinkPackingList","confirmedLinkCertificateOfOrigin","confirmedLinkInsuranceCertificate","confirmedLinkInspectionCertificate","confirmedLinkFumigationCertificate","confirmedLinkExportDeclaration","confirmedLinkLetterOfCredit","confirmedLinkDeliveryOrder","confirmedLinkCustomsDeclaration"];
function piLinkedCount(d){ return PI_LINK_FIELDS.filter(f=>d[f]).length; }


/* Purchase Order helpers (full 8-phase Procure-to-Pay lifecycle) */
function poLineTotal(row){ return (parseFloat(row.qty)||0)*(parseFloat(row.unitPrice)||0); }
function poGrandTotal(d){ return (d.poItems||[]).reduce((s,r)=>s+poLineTotal(r),0); }
function poPrNumberGen(d){
  if(!d.requestingDepartment || !d.prDate) return "Not yet generated — enter Requesting Department and PR Date to generate.";
  const seq = String((d.requestingDepartment||"").length*41 + (new Date(d.prDate).getDate()||1)).padStart(5,"0");
  const year = new Date(d.prDate).getFullYear() || new Date().getFullYear();
  return `PR/${year}/${seq}`;
}
function poRfqNumberGen(d){
  if(!d.selectedSupplierName || !d.rfqPreparedDate) return "Not yet generated — enter Selected Supplier and RFQ Date to generate.";
  const seq = String((d.selectedSupplierName||"").length*43).padStart(5,"0");
  const year = new Date(d.rfqPreparedDate).getFullYear() || new Date().getFullYear();
  return `RFQ/${year}/${seq}`;
}
function poGrnNumberGen(d){
  if(!d.poNumber || !d.shipmentReceivedDate) return "Not yet generated — enter PO Number and Shipment Received Date to generate.";
  const seq = String((d.poNumber||"").replace(/\D/g,"").slice(-6) || String((d.poNumber||"").length*47)).padStart(6,"0");
  const year = new Date(d.shipmentReceivedDate).getFullYear() || new Date().getFullYear();
  return `GRN/${year}/${seq}`;
}
const PO_LIFECYCLE_STAGES = ["Draft","Approved","Released","Accepted","Shipped","Received (GRN)","Invoiced","Paid","Closed"];
function poLifecycleStatus(d){
  if(d.poClosed) return "Closed";
  if(d.paymentReleased) return "Paid";
  if(d.invoiceApprovalStatus==="Approved") return "Invoiced";
  if(d.shipmentReceivedDate) return "Received (GRN)";
  if(d.dispatchDate) return "Shipped";
  if(d.supplierResponse==="Accepted"||d.supplierResponse==="Accepted with Changes") return "Accepted";
  if(d.poSentToSupplierDate) return "Released";
  if(d.poApprovalStatus==="Approved") return "Approved";
  if(d.poNumber) return "Draft";
  return "Requisition Stage";
}
function poThreeWayMatchOk(d){
  return !!(d.threeWayMatchPO && d.threeWayMatchGRN && d.threeWayMatchInvoice) && !d.discrepancyFound;
}

/* Fumigation Certificate helpers */
function fumAvgConcentration(d){
  const rows = d.fumReadings||[];
  const valid = rows.map(r=>parseFloat(r.concentration)).filter(v=>!isNaN(v));
  if(valid.length===0) return 0;
  return valid.reduce((s,v)=>s+v,0)/valid.length;
}

/* Certificate of Analysis helpers */
function coaOverallPass(d){
  const rows = d.testParams||[];
  if(rows.length===0) return false;
  return rows.every(r=>(r.status||"").trim().toLowerCase().startsWith("pass"));
}

/* Weight Certificate helpers */
function wcVGM(d){ return (parseFloat(d.containerTareWeight)||0)+(parseFloat(d.cargoNetWeight)||0)+(parseFloat(d.dunnageWeight)||0); }
function wcVariancePercent(d){
  const declared = parseFloat(d.declaredWeight)||0;
  if(declared===0) return 0;
  const vgm = wcVGM(d);
  return ((vgm-declared)/declared)*100;
}
function wcWithinTolerance(d){
  const threshold = parseFloat(d.toleranceThreshold)||5;
  return Math.abs(wcVariancePercent(d)) <= threshold;
}

/* Credit Note helpers */
function cnLineTotal(row){ return (parseFloat(row.qty)||0)*(parseFloat(row.unitPrice)||0); }
function cnCreditTotal(d){ return (d.cnItems||[]).reduce((s,r)=>s+cnLineTotal(r),0); }
function cnRevisedAmount(d){ return Math.max(0, (parseFloat(d.originalInvoiceAmount)||0) - cnCreditTotal(d)); }

/* Debit Note helpers */
function dnLineTotal(row){ return (parseFloat(row.qty)||0)*(parseFloat(row.unitPrice)||0); }
function dnDebitTotal(d){ return (d.dnItems||[]).reduce((s,r)=>s+dnLineTotal(r),0); }
function dnRevisedAmount(d){ return (parseFloat(d.originalInvoiceAmount)||0) + dnDebitTotal(d); }

/* Dock Receipt helpers */
function dockTotalCharges(d){ return (parseFloat(d.wharfageCharges)||0)+(parseFloat(d.terminalHandlingCharges)||0); }

/* Mate Receipt helpers (full 12-phase booking-to-B/L-exchange lifecycle) */
function mrContainerVGM(row){ return (parseFloat(row.tareWeight)||0)+(parseFloat(row.cargoWeight)||0); }
function mrNumberGen(d){
  if(!d.bookingReferenceNo || !d.issueDate) return "Not yet generated — enter a Booking Reference No. and Issue Date to generate.";
  const seq = String((d.bookingReferenceNo||"").replace(/\D/g,"").slice(-6) || "000001").padStart(6,"0");
  const year = new Date(d.issueDate).getFullYear() || new Date().getFullYear();
  return `MR/${year}/${seq}`;
}
function mrChargesTotal(d){
  return (d.mrCharges||[]).reduce((s,r)=>s+(parseFloat(r.amount)||0)+(parseFloat(r.tax)||0),0);
}
function mrIsClean(d){ return d.receiptCondition==="Clean Receipt — Good Order and Condition"; }
function mrPhaseStatus(d){
  return [
    {label:"1. Booking Reference", done: !!(d.bookingReferenceNo && d.shippingBillNo && d.chaName)},
    {label:"2. Shipper / Consignee / Notify", done: !!(d.shipperName && d.consigneeName && d.notifyPartyName)},
    {label:"3. Vessel & Voyage", done: !!(d.vesselName && d.vesselImoNumber && d.voyageNo && d.carrierName)},
    {label:"4. Port & Berth", done: !!(d.portOfLoading && d.portOfDischarge && d.berthJettyNo)},
    {label:"5. Cargo Description", done: !!(d.cargoDescription && d.hsCode && d.numberOfPackages)},
    {label:"6. Packing & Containers", done: !!((d.mrContainers||[]).some(r=>r.containerNo))},
    {label:"7. Pre-Loading Tally", done: !!(d.tallyClerkName && d.tallyDate && d.physicalConditionOnReceipt)},
    {label:"8. Loading & Stowage", done: !!(d.loadingEndDate && d.stevedoreCompanyName && d.stowagePosition)},
    {label:"9. Condition & Clausing", done: !!d.receiptCondition},
    {label:"10. Charges & Payment", done: !!(d.paymentConfirmed && (d.mrCharges||[]).length>0)},
    {label:"11. Mate's Signature & Issuance", done: !!(d.mateName && d.issueDate && d.issuedToName)},
    {label:"12. Document Linking & Closure", done: !!(d.recordClosed && d.closureDate)}
  ];
}
function mrOverallStatus(d){
  const phases = mrPhaseStatus(d);
  const doneCount = phases.filter(p=>p.done).length;
  if(doneCount===12) return {label:"Closed — All 12 Phases Complete", cls:"closed"};
  if(doneCount===0) return {label:"Not Started — Booking Reference Pending", cls:"pending"};
  return {label:`In Progress — ${doneCount} of 12 Phases Complete`, cls:"in-progress"};
}

/* Proof of Delivery helpers (full 4-phase lifecycle: prep, transit, verification/acceptance, POD collection) */
function podManifestNoGen(d){
  if(!d.doNumber || !d.deliveryDate) return "Not yet generated — enter DO Number and Delivery Date to generate.";
  const seq = String((d.doNumber||"").replace(/\D/g,"").slice(-6) || String((d.doNumber||"").length*53)).padStart(6,"0");
  const year = new Date(d.deliveryDate).getFullYear() || new Date().getFullYear();
  return `MAN/${year}/${seq}`;
}
function podNumberGen(d){
  if(!d.recipientNameFinal || !d.podDate) return "Not yet generated — enter Recipient Name and POD Date to generate.";
  const seq = String((d.recipientNameFinal||"").length*59 + (new Date(d.podDate).getDate()||1)).padStart(6,"0");
  const year = new Date(d.podDate).getFullYear() || new Date().getFullYear();
  return `POD/${year}/${seq}`;
}
function podPhaseStatus(d){
  return [
    {n:1, label:"Delivery Prep", done: !!(d.doNumber && d.inventoryReserved && d.driverSignedManifest)},
    {n:2, label:"Dispatch & Transit", done: !!(d.gpsActivated && d.trackingLinkShared)},
    {n:3, label:"Verification & Acceptance", done: !!d.customerApprovesShipment},
    {n:4, label:"POD Collection", done: !!d.podLocked}
  ];
}
function podLegalEvidenceCaptured(d){
  return [
    {label:"Signature", captured: !!d.signatureVisibilityVerified},
    {label:"GPS Location", captured: !!(d.gpsLatitude && d.gpsLongitude)},
    {label:"Photographs", captured: !!(d.photosOfPackages || d.photosOfLabels)},
    {label:"Barcode Scan", captured: !!d.packageBarcodeScanned},
    {label:"Timestamp", captured: !!(d.arrivalTimeRecorded && d.completionTimeRecorded)},
    {label:"Recipient ID", captured: !!d.recipientNameFinal}
  ];
}


function edShippingBillNoGen(d){
  if(!d.iecNumber || !d.buyerPORef) return "Not yet generated — enter IEC Number and Buyer PO Reference to generate.";
  const seq = String((d.iecNumber||"").replace(/\D/g,"").slice(-6) || String((d.iecNumber||"").length*29)).padStart(6,"0");
  return `SB/${new Date().getFullYear()}/${seq}`;
}
function edLeoNoGen(d){
  if(!d.leoGranted || !d.cargoRegistrationNo) return "Not yet granted.";
  const seq = String((d.cargoRegistrationNo||"").replace(/\D/g,"").slice(-6) || String((d.cargoRegistrationNo||"").length*31)).padStart(6,"0");
  return `LEO/${new Date().getFullYear()}/${seq}`;
}
function edPhaseStatus(d){
  return [
    {label:"Preparation", done: !!(d.iecNumber && d.adCode && d.hsCodeClassified && d.exportScheme)},
    {label:"Documents", done: !!(d.commercialInvoiceNo && d.packingListNo && d.documentConsistencyVerified)},
    {label:"Filing", done: !!d.submittedElectronicallyToCustoms},
    {label:"RMS / Processing", done: !!(d.rmsAssessmentResult && d.customsApprovalGranted)},
    {label:"Examination / LEO", done: !!d.leoGranted},
    {label:"Shipment / Departure", done: !!d.exportOfficiallyCompleted},
    {label:"Financial Compliance", done: !!(d.adBankRealizationReported && d.forexComplianceConfirmed)},
    {label:"Post-Export Closure", done: !!d.exportTransactionClosed}
  ];
}
function edOverallStatus(d){
  const phases = edPhaseStatus(d);
  if(d.exportTransactionClosed) return {label:"Closed — Export Transaction Complete", cls:"closed"};
  if(d.customsNoticeReceived && !d.customsNoticeResponseDetails) return {label:"On Hold — Customs Notice Pending Response", cls:"hold"};
  if(d.queryGenerated && !d.exporterQueryReply) return {label:"On Hold — Customs Query Pending Reply", cls:"hold"};
  const doneCount = phases.filter(p=>p.done).length;
  if(doneCount===0) return {label:"Not Started", cls:"pending"};
  return {label:`In Progress — ${doneCount} of 8 Phases Complete`, cls:"in-progress"};
}


const MSDS_PICTOGRAMS = ["Flame","Corrosion","Exclamation Mark","Health Hazard","Gas Cylinder","Skull and Crossbones","Environment","Oxidizer","Explosive"];
function msdsPictogramFields(){
  return MSDS_PICTOGRAMS.map(p=>"pictogram"+p.replace(/[^A-Za-z]/g,""));
}
function msdsActivePictograms(d){
  const fields = msdsPictogramFields();
  return MSDS_PICTOGRAMS.filter((p,i)=>d[fields[i]]);
}
function msdsSectionStatus(d){
  return [
    {n:1, label:"Identification", done: !!(d.productName && d.manufacturerName && d.emergencyPhone)},
    {n:2, label:"Hazard(s) Identification", done: !!(d.signalWord && d.hazardStatements)},
    {n:3, label:"Composition / Ingredients", done: !!((d.msdsComposition||[]).some(r=>r.componentName))},
    {n:4, label:"First-Aid Measures", done: !!(d.firstAidInhalation && d.firstAidSkin && d.firstAidEye)},
    {n:5, label:"Fire-Fighting Measures", done: !!d.suitableExtinguishingMedia},
    {n:6, label:"Accidental Release Measures", done: !!d.spillCleanupProcedure},
    {n:7, label:"Handling and Storage", done: !!(d.handlingPrecautions && d.storageConditions)},
    {n:8, label:"Exposure Controls / PPE", done: !!d.engineeringControls},
    {n:9, label:"Physical & Chemical Properties", done: !!(d.flashPoint && d.boilingPoint)},
    {n:10, label:"Stability and Reactivity", done: !!d.chemicalStability},
    {n:11, label:"Toxicological Information", done: !!d.routesOfExposure},
    {n:12, label:"Ecological Information", done: !!d.ecotoxicityAquatic},
    {n:13, label:"Disposal Considerations", done: !!d.disposalMethods},
    {n:14, label:"Transport Information", done: !!d.unNumber},
    {n:15, label:"Regulatory Information", done: !!d.tscaInventoryStatus},
    {n:16, label:"Other Information", done: !!(d.sdsPreparedBy && d.sdsRevisionDate)}
  ];
}


function sdNumberGen(d){
  if(!d.shipperName || !d.signDate) return "Not yet generated — enter Shipper Details and a Date to generate.";
  const seq = String((d.shipperName||"").replace(/[^0-9]/g,"").slice(-6) || String(d.shipperName||"").length).padStart(6,"0");
  const year = new Date(d.signDate).getFullYear() || new Date().getFullYear();
  return `SD/${year}/${seq}`;
}
function sdOverallCleared(d){
  return !!(
    d.shipperSecurityProfileApproved &&
    d.documentationApproved &&
    d.finalApprovalStatus==="Approved" &&
    !d.prohibitedItemsDetected &&
    !d.securityIncidentReported &&
    !d.tamperingDetected
  );
}
function sdPhaseStatus(d){
  return [
    {n:1, label:"Security Planning", done: !!(d.shipmentType && d.securityLevelAssigned)},
    {n:2, label:"Shipper Verification", done: !!(d.exporterIdentityVerified && d.sanctionsWatchlistScreened && d.shipperSecurityProfileApproved)},
    {n:3, label:"Cargo Inspection", done: !!(d.physicalCargoInspectionDone && d.inspectionFindingsRecorded)},
    {n:4, label:"Container Security", done: !!(d.highSecuritySealInstalled && d.sealNumber)},
    {n:5, label:"Document Review", done: !!d.documentationApproved},
    {n:6, label:"Declaration Prep", done: !!(d.cargoSecurityStatus && d.screeningMethodDeclared)},
    {n:7, label:"Approval", done: !!(d.finalApprovalStatus && d.finalApprovalStatus!=="Pending")},
    {n:8, label:"Submission", done: !!d.submissionConfirmationRecorded},
    {n:9, label:"Transport Monitoring", done: !!d.transportMonitoringClosed},
    {n:10, label:"Final Closure", done: !!(d.securityFileClosed && d.securityDeclarationArchived)}
  ];
}

/* Duty Calculation helpers (full 10-phase IGST/BCD/SWS cascade, IMDG-independent — pure customs math) */
function dcHsCodeDisplay(d){ return d.hsCode8DigitNational || d.hsCode6Digit || "—"; }
function dcFobValue(d){
  const line = (parseFloat(d.unitPrice)||0)*(parseFloat(d.quantityImported)||0);
  const net = line - (parseFloat(d.discountAmount)||0) + (parseFloat(d.assistsValue)||0);
  return Math.max(0, net);
}
function dcFreightTotal(d){
  return (parseFloat(d.oceanFreight)||0)
    + (d.inlandFreightIncludable ? (parseFloat(d.inlandFreightAmount)||0) : 0)
    + (parseFloat(d.loadingCharges)||0)
    + (parseFloat(d.handlingCharges)||0);
}
function dcInsuranceTotal(d){
  return (parseFloat(d.marineInsurancePremium)||0) + (parseFloat(d.additionalInsuranceCoverage)||0);
}
function dcCifValueForeign(d){
  return dcFobValue(d) + dcFreightTotal(d) + dcInsuranceTotal(d);
}
function dcCifValueINR(d){
  return dcCifValueForeign(d) * (parseFloat(d.customsNotifiedExchangeRate)||0);
}
function dcLandingCharges(d){
  return d.landingChargesApplicable ? dcCifValueINR(d) * (parseFloat(d.landingChargesPercent)||0)/100 : 0;
}
function dcAssessableValue(d){
  return dcCifValueINR(d) + dcLandingCharges(d) + (parseFloat(d.otherValuationAdjustments)||0);
}
function dcBcdAmount(d){
  return dcAssessableValue(d) * (parseFloat(d.bcdRate)||0)/100;
}
function dcSwsAmount(d){
  return dcBcdAmount(d) * (parseFloat(d.swsRate)||0)/100;
}
function dcAdditionalDutiesTotal(d){
  return (d.additionalDuties||[]).reduce((s,r)=>s+(parseFloat(r.amount)||0),0);
}
function dcIgstBase(d){
  return dcAssessableValue(d) + dcBcdAmount(d) + dcSwsAmount(d) + dcAdditionalDutiesTotal(d);
}
function dcIgstAmount(d){
  return dcIgstBase(d) * (parseFloat(d.igstRate)||0)/100;
}
function dcTotalCustomsDuty(d){
  return dcBcdAmount(d) + dcSwsAmount(d) + dcAdditionalDutiesTotal(d) + dcIgstAmount(d);
}
function dcTotalLandedCost(d){
  return dcAssessableValue(d) + dcTotalCustomsDuty(d);
}
function dcWorksheetNoGen(d){
  if(!d.invoiceNo || !d.signDate) return "Not yet generated — enter an Invoice No. and Date to generate.";
  const seq = String((d.invoiceNo||"").replace(/\D/g,"").slice(-6) || "000001").padStart(6,"0");
  const year = new Date(d.signDate).getFullYear() || new Date().getFullYear();
  return `DC/${year}/${seq}`;
}
function dcPhaseStatus(d){
  return [
    {label:"Product Classification", done: !!(d.hsCode6Digit && d.tariffClassificationVerified && d.regulatoryRequirementsRecorded)},
    {label:"Customs Valuation", done: !!(d.unitPrice && d.quantityImported && d.oceanFreight!==undefined && d.marineInsurancePremium!==undefined)},
    {label:"Exchange Rate", done: !!(d.customsNotifiedExchangeRate && d.exchangeRateNotificationDate)},
    {label:"Assessable Value", done: dcAssessableValue(d)>0},
    {label:"BCD", done: !!d.bcdRate},
    {label:"SWS", done: !!d.swsRate},
    {label:"Additional Duties", done: !!(d.additionalDutiesReviewed || (d.additionalDuties||[]).length===0)},
    {label:"IGST", done: !!d.igstRate},
    {label:"Final Assessment", done: dcTotalCustomsDuty(d)>0},
    {label:"Payment & Clearance", done: !!(d.goodsReleased && d.oocNumber)}
  ];
}


/* Dangerous Goods Declaration helpers (full 8-phase, 96-step IMDG-aligned lifecycle) */
function dgdNumberGen(d){
  if(!d.bookingNo || !d.signDate) return "Not yet generated — enter a Booking Number and Date to generate.";
  const seq = String((d.bookingNo||"").replace(/\D/g,"").slice(-6) || "000001").padStart(6,"0");
  const year = new Date(d.signDate).getFullYear() || new Date().getFullYear();
  return `DGD/${year}/${seq}`;
}
function dgdPrimaryItem(d){ return (d.dgItems||[])[0] || {}; }
function dgdPhaseStatus(d){
  return [
    {label:"1. DG Identification", done: !!(d.dgIdentificationRecorded && d.primaryUnNumber && d.primaryHazardClass)},
    {label:"2. Classification & Packaging", done: !!(d.packagingInspectionCompleted && d.imdgPackingInstruction)},
    {label:"3. Marking & Labelling", done: !!d.finalMarkingInspectionCompleted},
    {label:"4. Container / Vehicle Loading", done: !!(d.containerSealed && d.containerPlacardsApplied)},
    {label:"5. DG Declaration Preparation", done: !!(d.declarationStatementCompleted && (d.dgItems||[]).some(r=>r.unNumber))},
    {label:"6. Verification & Compliance", done: !!d.complianceReviewCompleted},
    {label:"7. Approval & Certification", done: !!(d.approvedForShipment && d.signName)},
    {label:"8. Distribution & Records", done: !!(d.documentationProcessClosed && d.archivedSignedDeclaration)}
  ];
}
function dgdOverallStatus(d){
  const phases = dgdPhaseStatus(d);
  const doneCount = phases.filter(p=>p.done).length;
  if(doneCount===8) return {label:"Closed — All 8 Phases Complete", cls:"closed"};
  if(doneCount===0) return {label:"Not Started", cls:"pending"};
  return {label:`In Progress — ${doneCount} of 8 Phases Complete`, cls:"in-progress"};
}

/* Sales Order helpers (full 10-phase request-to-fulfillment lifecycle) */
function soLineRowTotal(row){ return (parseFloat(row.qty)||0)*(parseFloat(row.unitPrice)||0); }
function soLineItemsTotal(d){ return (d.soLineItems||[]).reduce((s,r)=>s+soLineRowTotal(r),0); }
function soNumberGen(d){
  if(!d.customerId || !d.orderDate) return "Not yet generated — enter a Customer ID and Order Date above to generate.";
  const seq = String((d.customerId||"").replace(/\D/g,"").slice(-6) || "000001").padStart(6,"0");
  const year = new Date(d.orderDate).getFullYear() || new Date().getFullYear();
  return `SO/${year}/${seq}`;
}
function soDiscountsTotal(d){
  const base = soLineItemsTotal(d);
  const custDisc = base*(parseFloat(d.customerDiscountPercent)||0)/100;
  const promoDisc = base*(parseFloat(d.promotionalDiscountPercent)||0)/100;
  const itemDisc = parseFloat(d.itemDiscountAmount)||0;
  return custDisc+promoDisc+itemDisc;
}
function soTaxableValue(d){
  const base = soLineItemsTotal(d);
  const afterDiscount = Math.max(0, base - soDiscountsTotal(d));
  const addOns = (parseFloat(d.freightCharges)||0)+(parseFloat(d.packingCharges)||0)+(parseFloat(d.insuranceCharges)||0);
  return afterDiscount + addOns;
}
function soGstAmount(d){ return soTaxableValue(d)*(parseFloat(d.gstVatRate)||0)/100; }
function soTotalOrderValue(d){ return soTaxableValue(d)+soGstAmount(d); }
function soDeliveryVarianceDays(d){
  if(!d.requestedDeliveryDate || !d.confirmedDeliveryDate) return 0;
  const req = new Date(d.requestedDeliveryDate), conf = new Date(d.confirmedDeliveryDate);
  if(isNaN(req.getTime())||isNaN(conf.getTime())) return 0;
  return Math.round((conf.getTime()-req.getTime())/86400000);
}
function soCreditStatus(d){
  const limit = parseFloat(d.creditLimitAmount)||0;
  const outstanding = parseFloat(d.outstandingBalance)||0;
  if(!d.creditLimitAmount) return {label:"Not Checked", cls:"pending"};
  const exposure = outstanding + soTotalOrderValue(d);
  return exposure <= limit ? {label:"Within Credit Limit", cls:"within"} : {label:"Exceeds Credit Limit", cls:"exceeds"};
}
function soPhaseStatus(d){
  return [
    {label:"1. Customer & Order Init", done: !!(d.customerId && d.customerStatusVerified && d.sellerName && d.salesOffice && d.salespersonName)},
    {label:"2. Order Header", done: !!(d.orderDate && d.customerPoNumber && d.orderType)},
    {label:"3. Line Items", done: !!((d.soLineItems||[]).some(r=>r.productCode))},
    {label:"4. Pricing & Tax", done: !!(d.gstVatRate && soTotalOrderValue(d)>0)},
    {label:"5. Inventory Check", done: !!(d.stockConfirmedBy && d.stockConfirmationDate)},
    {label:"6. Delivery & Shipping", done: !!(d.confirmedDeliveryDate && d.carrierName)},
    {label:"7. Payment & Credit", done: !!(d.paymentDueDate && d.paymentMethod && (!d.creditApprovalRequired || d.creditApprovedBy))},
    {label:"8. Review & Approval", done: !!(d.orderLocked && d.finalApprovalStatus==="Approved")},
    {label:"9. SO Confirmation", done: !!(d.orderConfirmationSent && d.confirmationDate)},
    {label:"10. Fulfillment & Integration", done: !!(d.soClosed && d.erpLedgerUpdated)}
  ];
}
function soOverallStatus(d){
  const phases = soPhaseStatus(d);
  const doneCount = phases.filter(p=>p.done).length;
  if(doneCount===10) return {label:"Order Closed — All 10 Phases Complete", cls:"closed"};
  if(doneCount===0) return {label:"Order Initiated — Awaiting Processing", cls:"pending"};
  return {label:`In Progress — ${doneCount} of 10 Phases Complete`, cls:"in-progress"};
}

/* E-Way Bill helpers */
function ewbTaxableTotal(d){ return (d.ewbItems||[]).reduce((s,r)=>s+(parseFloat(r.taxableValue)||0),0); }
function ewbTaxAmount(d){
  const total = ewbTaxableTotal(d);
  const rate = (parseFloat(d.cgstRate)||0)+(parseFloat(d.sgstRate)||0)+(parseFloat(d.igstRate)||0);
  return total*rate/100;
}
function ewbGrandTotal(d){ return ewbTaxableTotal(d)+ewbTaxAmount(d); }
function ewbValidityDays(d){
  const km = parseFloat(d.distanceKm)||0;
  return Math.max(1, Math.ceil(km/200));
}
function ewbValidUntil(d){
  if(!d.generatedDate) return "—";
  const base = new Date(d.generatedDate);
  if(isNaN(base.getTime())) return "—";
  const days = ewbValidityDays(d);
  const until = new Date(base.getTime()+days*86400000);
  return until.toISOString().slice(0,10);
}
function ewbIsExpired(d){
  const until = new Date(ewbValidUntil(d));
  if(isNaN(until.getTime())) return false;
  return until.getTime() < Date.now();
}

/* Arrival Notice helpers */
function anLastFreeDay(d){
  if(!d.actualArrivalDate) return null;
  const base = new Date(d.actualArrivalDate);
  if(isNaN(base.getTime())) return null;
  const freeDays = parseInt(d.freeDays)||7;
  return new Date(base.getTime()+freeDays*86400000);
}
function anLastFreeDayStr(d){
  const dt = anLastFreeDay(d);
  return dt ? dt.toISOString().slice(0,10) : "—";
}
function anDemurrageDays(d){
  const lastFree = anLastFreeDay(d);
  if(!lastFree) return 0;
  return Math.max(0, Math.floor((Date.now()-lastFree.getTime())/86400000));
}
function anDemurrageAccrued(d){ return anDemurrageDays(d)*(parseFloat(d.demurrageRatePerDay)||0); }
function anTotalCharges(d){
  return (parseFloat(d.freightDue)||0)+(parseFloat(d.thcCharges)||0)+(parseFloat(d.docFee)||0)+anDemurrageAccrued(d);
}

/* Inspection Certificate helpers (full pre-shipment inspection lifecycle, AQL-correct defect classification) */
function icQuantityVariancePercent(d){
  const declared = parseFloat(d.declaredQuantity)||0;
  if(declared===0) return 0;
  const verified = parseFloat(d.verifiedQuantity)||0;
  return ((verified-declared)/declared)*100;
}
function icWithinTolerance(d){
  const threshold = parseFloat(d.toleranceThreshold)||2;
  return Math.abs(icQuantityVariancePercent(d)) <= threshold;
}
function icCriticalPass(d){ return (parseInt(d.criticalDefectsFound)||0) <= (parseInt(d.criticalAcceptNumber)||0); }
function icMajorPass(d){ return (parseInt(d.majorDefectsFound)||0) <= (parseInt(d.majorAcceptNumber)||0); }
function icMinorPass(d){ return (parseInt(d.minorDefectsFound)||0) <= (parseInt(d.minorAcceptNumber)||0); }
function icDefectsPass(d){ return icCriticalPass(d) && icMajorPass(d) && icMinorPass(d); }
function icPackingPass(d){ return d.packingCondition==="Satisfactory"; }
function icTestPass(d){ return !d.laboratoryTestingRequired || d.testResult==="Pass" || d.testResult==="Not Applicable"; }
function icOverallPass(d){
  return icWithinTolerance(d) && icDefectsPass(d) && icPackingPass(d) && icTestPass(d);
}
function icCertNoGen(d){
  if(!d.poNumber || !d.issueDate) return "Not yet generated — enter a PO Number and Issue Date to generate.";
  const seq = String((d.poNumber||"").replace(/\D/g,"").slice(-6) || "000001").padStart(6,"0");
  const year = new Date(d.issueDate).getFullYear() || new Date().getFullYear();
  return `IC/${year}/${seq}`;
}


