function cpcAllItems(){ return CPC_CHECKLIST_GROUPS.flatMap(g=>g.items); }
function cpcChecklistScore(d){ return cpcAllItems().reduce((n,item)=> n + (d[item.key] ? 1 : 0), 0); }
function cpcChecklistTotal(){ return cpcAllItems().length; }
function cpcPhaseStatus(d){
  return CPC_CHECKLIST_GROUPS.map(g=>{
    const done = g.items.filter(item=>d[item.key]).length;
    return {label:g.phase, done, total:g.items.length, complete: done===g.items.length};
  });
}
function cpcCertificateNoGen(d){
  if(!d.containerNo || !d.issueDate) return "Not yet generated — enter Container No. and Issue Date to generate.";
  const seq = String((d.containerNo||"").replace(/\D/g,"").slice(-6) || "000001").padStart(6,"0");
  const year = new Date(d.issueDate).getFullYear() || new Date().getFullYear();
  return `CPC/${year}/${seq}`;
}
function cpcGrossWeight(d){ return (parseFloat(d.containerGrossWeight)||0); }


/* Booking Confirmation helpers (full 8-phase freight booking lifecycle) */
function bcIsPassed(dateStr){
  if(!dateStr) return false;
  const dt = new Date(dateStr);
  if(isNaN(dt.getTime())) return false;
  return dt.getTime() < Date.now();
}
function bcPhaseStatus(d){
  return [
    {label:"Request & Space Check", done: !!(d.spaceAvailabilityChecked && d.carrierInternalRefNo)},
    {label:"Vessel & Voyage Nomination", done: !!(d.bookingNo && d.vesselName && d.voyageNumber)},
    {label:"Container Allocation", done: !!(d.containerReleaseOrderIssued && d.emptyPickupDepot)},
    {label:"Parties & Cargo", done: !!(d.shipperName && d.consigneeName && d.commodityDescription)},
    {label:"Cutoff Timeline", done: !!(d.siCutoff && d.vgmCutoff && d.gateInCutoff)},
    {label:"Freight & Validity", done: !!(d.rateAgreed && d.bookingValidUntil)},
    {label:"Special Cargo Compliance", done: !(d.hazardousCargo || d.outOfGauge) || !!d.carrierPriorApprovalObtained},
    {label:"Finalization", done: !!d.bookingFinalized}
  ];
}
function bcOverallStatus(d){
  if(d.bookingFinalized) return {label:"Finalized — Handed Over to Shipping Instructions", cls:"finalized"};
  if(d.rolledToNextSailing) return {label:"Rolled to Next Sailing", cls:"rolled"};
  if(d.amendmentMade) return {label:"Amended — Pending Reconfirmation", cls:"amended"};
  const doneCount = bcPhaseStatus(d).filter(p=>p.done).length;
  if(doneCount===0) return {label:"Booking Requested — Not Yet Confirmed", cls:"notstarted"};
  return {label:`In Progress — ${doneCount} of 8 Phases Complete`, cls:"progress"};
}

/* Out of Charge helpers (mostly auto-derived — mirrors how ICES actually generates OOC from a few source facts) */
function oocDutyBalance(d){ return (parseFloat(d.totalDutyAssessedAmount)||0) - (parseFloat(d.dutyPaidAmount)||0); }
function oocPaymentStatus(d){
  if(!d.dutyPaidAmount || !d.totalDutyAssessedAmount) return {label:"Not Yet Verified", cls:"pending"};
  const bal = oocDutyBalance(d);
  if(Math.abs(bal) < 0.01) return {label:"Fully Paid — Matched to Assessment", cls:"ok"};
  if(bal > 0) return {label:`Short Paid — Balance Due ${bal.toFixed(2)}`, cls:"bad"};
  return {label:`Overpaid — Refund Due ${Math.abs(bal).toFixed(2)}`, cls:"warn"};
}
function oocExaminationStatus(d){
  if(d.rmsFacilitationLevel==="Facilitated — No Examination") return {label:"Facilitated — No Examination Required", cls:"ok"};
  if(!d.examinationResult) return {label:"Examination Pending", cls:"pending"};
  if(d.examinationResult==="Examined — Discrepancy Noted") return {label:"Discrepancy Noted — Referred for Further Assessment", cls:"bad"};
  return {label:"Examined — No Discrepancy", cls:"ok"};
}
function oocApplicableComplianceChecks(d){
  const checks = [];
  if(d.licenseRequired) checks.push(!!d.licenseVerified);
  if(d.certificatesRequired) checks.push(!!d.certificatesVerified);
  if(d.antiDumpingApplicable) checks.push(!!d.antiDumpingVerified);
  return checks;
}
function oocComplianceScore(d){
  const checks = oocApplicableComplianceChecks(d);
  if(checks.length===0) return {passed:0, total:0, pct:100};
  const passed = checks.filter(Boolean).length;
  return {passed, total:checks.length, pct: Math.round((passed/checks.length)*100)};
}
function oocComplianceOk(d){
  const score = oocComplianceScore(d);
  return score.passed === score.total;
}
function oocReleaseReady(d){
  const paymentOk = Math.abs(oocDutyBalance(d)) < 0.01 && !!d.dutyPaidAmount && !!d.totalDutyAssessedAmount;
  const examOk = d.rmsFacilitationLevel==="Facilitated — No Examination" || d.examinationResult==="Examined — No Discrepancy";
  return paymentOk && examOk && oocComplianceOk(d);
}
function oocNumberGen(d){
  if(!d.boeNumber || !d.issueDate) return "Not yet generated — enter Bill of Entry No. and Issue Date to generate.";
  const seq = String((d.boeNumber||"").replace(/\D/g,"").slice(-6) || String((d.boeNumber||"").length*37)).padStart(6,"0");
  const year = new Date(d.issueDate).getFullYear() || new Date().getFullYear();
  return `OOC/${year}/${seq}`;
}
function oocGatePassNoGen(d){
  if(!d.containerNo) return "Not yet generated — enter Container No. to generate.";
  const seq = String((d.containerNo||"").replace(/\D/g,"").slice(-5) || "00001").padStart(5,"0");
  return `GP-${seq}`;
}

